//! The Diplomat Peak — Das letzte Kapitel.
//!
//! A first person horror walk through an abandoned mountain hotel in Baguio.
//! Everything below is procedural: there is not a single imported model or
//! image in this game that was not generated by the tools in `tools/`.
//!
//! The shared code lives in `src/lib.rs`, because the level editor
//! (`src/bin/editor.rs`) is built from the same modules.

use bevy::prelude::*;
use bevy::window::WindowResolution;

use diplomat_peak::audio::AudioPlugin;
use diplomat_peak::body::BodyPlugin;
use diplomat_peak::core::{AppState, CorePlugin};
use diplomat_peak::custom::CustomLevelPlugin;
use diplomat_peak::finale::FinalePlugin;
use diplomat_peak::fx::FxPlugin;
use diplomat_peak::interact::InteractPlugin;
use diplomat_peak::lighting::LightingPlugin;
use diplomat_peak::player::PlayerPlugin;
use diplomat_peak::puzzles::PuzzlesPlugin;
use diplomat_peak::story::StoryPlugin;
use diplomat_peak::ui::UiPlugin;
use diplomat_peak::world::WorldPlugin;

fn main() {
    App::new()
        .add_plugins(
            DefaultPlugins
                .set(WindowPlugin {
                    primary_window: Some(Window {
                        title: "The Diplomat Peak — Das letzte Kapitel".to_string(),
                        resolution: WindowResolution::new(1600.0, 900.0),
                        resizable: true,
                        ..default()
                    }),
                    ..default()
                })
                .set(ImagePlugin::default_linear()),
        )
        .init_state::<AppState>()
        .add_plugins((
            CorePlugin,
            AudioPlugin,
            BodyPlugin,
            PlayerPlugin,
            InteractPlugin,
            UiPlugin,
            WorldPlugin,
            LightingPlugin,
            FxPlugin,
            StoryPlugin,
            PuzzlesPlugin,
            FinalePlugin,
            CustomLevelPlugin,
        ))
        .run();
}
